edits.before:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {
        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

edits.after:
self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {
        var opts = self._o;
        function isDateAllowed(date) {
            if (opts.minDate && date < opts.minDate) return false;
            if (opts.maxDate && date > opts.maxDate) return false;
            if (opts.disableWeekends) {
                var day = date.getDay();
                if (day === 0 || day === 6) return false;
            }
            if (opts.disableDayFn && typeof opts.disableDayFn === 'function') {
                if (opts.disableDayFn(date)) return false;
            }
            return true;
        }

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                var newDate = self.getDate() || new Date();
                do {
                    newDate = new Date(newDate.getTime() - 24*60*60*1000);
                } while (!isDateAllowed(newDate));
                self.setDate(newDate);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                var newDate = self.getDate() || new Date();
                do {
                    newDate = new Date(newDate.getTime() + 24*60*60*1000);
                } while (!isDateAllowed(newDate));
                self.setDate(newDate);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};
